require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';send_cors_headers();$context=require_admin('influencers.manage');$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->query('SELECT c.*,(SELECT COUNT(*) FROM influencer_referral_links l WHERE l.campaign_id=c.id) influencer_count FROM influencer_campaigns c ORDER BY c.created_at DESC');json_response(200,['success'=>true,'campaigns'=>$stmt->fetchAll()]);}if($method==='POST'){$body=get_json_body();$action=trim((string)($body['action']??'create'));if($action==='assign'){$campaign=trim((string)($body['campaign_id']??''));$influencer=trim((string)($body['influencer_id']??''));$check=$db->prepare('SELECT id FROM influencers WHERE id=:id AND status="active"');$check->execute(['id'=>$influencer]);if(!$check->fetch())json_response(422,['success'=>false,'message'=>'Creator must be approved and active.']);$id=uuid_string();$code=strtoupper(trim((string)($body['code']??'CI'.substr(str_replace('-','',$influencer),0,6).substr(str_replace('-','',$campaign),0,4))));$db->prepare('INSERT INTO influencer_referral_links (id,influencer_id,campaign_id,code,destination_url,status,created_at) VALUES (:id,:owner,:campaign,:code,:url,"active",UTC_TIMESTAMP())')->execute(['id'=>$id,'owner'=>$influencer,'campaign'=>$campaign,'code'=>$code,'url'=>trim((string)($body['destination_url']??'/'))]);json_response(201,['success'=>true,'message'=>'Creator assigned to campaign.','referral_code'=>$code]);}$name=trim((string)($body['name']??''));$description=trim((string)($body['description']??''));$type=trim((string)($body['commission_type']??''));$value=round((float)($body['commission_value']??0),2);$start=strtotime((string)($body['starts_at']??''));$end=strtotime((string)($body['ends_at']??''));if(mb_strlen($name)<3||mb_strlen($description)<20||!in_array($type,['percent','fixed'],true)||$value<=0||$start===false||$end===false||$end<=$start)json_response(422,['success'=>false,'message'=>'Campaign details are invalid.']);$id=uuid_string();$db->prepare('INSERT INTO influencer_campaigns (id,name,description,commission_type,commission_value,attribution_days,starts_at,ends_at,eligibility_json,disclosure_text,status,created_by,created_at,updated_at) VALUES (:id,:name,:description,:type,:value,:days,:starts,:ends,:eligibility,:disclosure,:status,:admin,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$id,'name'=>$name,'description'=>$description,'type'=>$type,'value'=>$value,'days'=>max(1,min(90,(int)($body['attribution_days']??30))),'starts'=>gmdate('Y-m-d H:i:s',$start),'ends'=>gmdate('Y-m-d H:i:s',$end),'eligibility'=>json_encode((array)($body['eligibility']??[])),'disclosure'=>trim((string)($body['disclosure_text']??'Paid partnership with Conscious Indi.')),'status'=>in_array($body['status']??'draft',['draft','active','paused'],true)?$body['status']:'draft','admin'=>$context['admin']['id']]);json_response(201,['success'=>true,'message'=>'Campaign created.','campaign_id'=>$id]);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
